In this section, we focus on the $L_2(7)$-family and determine its monodromy and period domain. In the end, we characterize the quotient curve $\Gamma_{T_1}\backslash\DD_{T_1}$ in an explicit way. For convenience, we use notation $T$ instead of $T_1$, $\Gamma$ instead of $\Gamma_{T_1}$ and $\Phi$ instead of $\Phi_{1}$ through this section. The calculation is inspired by \cite{dolgachev1996mirror}.

\subsection{Calculation of the Lattice $T$} 
\label{conslatL27}
We compute the lattice corresponding to the local period domain of $L_{2}(7)$-family. We mainly use Conway-Sloane's notation \cite[Chapter 15]{conway2013sphere} and the classification result of H\"{o}hn--Mason \cite[\S 4]{hohn2016290}. The reader can also refer to \cite[Appendix A]{laza2022automorphisms} for a brief introduction to the Conway-Sloane symbol.
\begin{defn}
A pair $(G, S)$ is called a Leech pair, if $S$ is a positive definite even lattice with no vectors of norm two, and $G$ is a finite group acting faithfully on $S$ such that the induced action of $G$ on the discriminant group $A_S$ is trivial, and the invariant sublattice $S^G$ is trivial.
\end{defn}

By \cite[Appendix B.2]{gaberdiel6symmetries} (see also \cite[Corollary 4.19]{marquand2025finite} and \cite[Lemma 1.1]{zheng2025lemmaleechlikelattices}), there is the following useful lemma: 
\begin{lem}
\label{lemma: leech pair}
Suppose $(G,S)$ is a Leech pair, and $\rank(S)+l(A_S)\le 24$. Then there exists a primitive embedding of $S$ into the Leech lattice $\LL$.
\end{lem}

Now let $G=L_2(7)$, and $S$ the coinvariant lattice of the action of $G$ on $\Lambda_0$. By \cite[Lemma 4.2]{laza2022automorphisms}, $(G,S)$ is a Leech pair satisfying the condition in Lemma \ref{lemma: leech pair}. Then there is a primitive embedding $S\hookrightarrow \LL$. Thus the $L_{2}(7)$-action on $S$ can be extended to $\mathbb{L}$, such that $S$ is the coinvariant lattice in $\mathbb{L}$. It is known from \cite{laza2022automorphisms} that the invariant sublattice $\mathbb{L}^{G}$ corresponds to \cite[Table 1, item 77]{hohn2016290}, which has discriminant form $q_{S}=4_{1}^{+1}7^{+2}$. And $S$ is the orthogonal complement of $\mathbb{L}^{G}$ in $\LL$, so $S$ has discriminant form $q_{S}=4_{7}^{+1}7^{+2}$. The lattice $T$ is the orthogonal complement of $S$ in $\Lambda_{0}$, and thus $T$ has signature $(1,2)$. We have the following embeddings:
\[
S\oplus E_{6} \hookrightarrow \Lambda_{0}\oplus E_{6}\hookrightarrow \text{\Rmnum{2}}_{26,2}. \]
The lattice $\text{\Rmnum{2}}_{26,2}$ is the even unimodular lattice of signature $(26,2)$, known as the Borcherds lattice. The lattice $T$ is the orthogonal complement of $S\oplus E_{6}$ in $\text{\Rmnum{2}}_{26,2}$. Then $q_T=4_{1}^{+1}7^{+2}3^{-1}$. By \cite[Theorem 1.13.2]{Nikulin_1980}, such $T$ is unique. One can directly construct a Gram matrix for $T$ with respect to certain basis as below:
\begin{equation}
    \label{equation: gram matrix of T}
\begin{pmatrix}
-2 & 1 & 0 \\ 1 & 10 & 0 \\ 0 & 0 & -28
\end{pmatrix}.
\end{equation}



\subsection{Characterization of $\Gamma$}
\label{subsection: chara of Gamma L27}
By abuse of notation, we denote the above matrix by $T$. 

According to \cite[\S 4.1.2]{laza2022automorphisms}, $(L_2(7), S)$ is a saturated Leech pair and therefore $L_2(7) = \{h \in \widehat{\Gamma}|h|_T = \Id_T\}$. Now let $N$ denote the normalizer of $L_2(7)$ inside $\widehat{\Gamma}$. For each element $f \in N$ and $h \in L_2(7)$, $f^{-1}hf = h^{\prime}$ for some $h^{\prime} \in L_2(7)$. Therefore, for any $t \in T$, we have $h(f(t)) = f(t)$, i.e. $f(t)$ is $L_2(7)$-invariant. By definition, we have $f(t) \in T$. Therefore, we can restrict $f$ on $T$. When forming quotients, there is no difference between considering $N$ or its image in $\rO^+(T)$ via restriction. Therefore, we denote $\Gamma = \mathrm{Im}(N \to \rO^+(T))$. We have the following characterization of $\Gamma$. 
\begin{prop}
    Recall that the discriminant group of $T$ is isomorphic to $\ZZ/4\ZZ \oplus (\ZZ/7\ZZ)^2\oplus\ZZ/3\ZZ$. An element $f \in \rO^+(T)$ is in $\Gamma$ if and only if $\overline{f}|_{\ZZ/3\ZZ}$ is trivial. 
\end{prop}
\label{gam}
\begin{proof}
From \cite[\S 4]{hohn2016290}, the discriminant group $A_S$ of $S$ is isomorphic to $\ZZ/4\ZZ \oplus (\ZZ/7\ZZ)^2$. For lattice $\Lambda_0$, we have $A_{\Lambda_0}\cong \ZZ/3\ZZ$. Let $A_T$ denote the discriminant group of $T$. From their discriminant groups we see that $\Lambda_0/(S\oplus T)$ is isomorphic to $\ZZ/4\ZZ \oplus (\ZZ/7\ZZ)^2$. Let $H_S = A_S$ and $H_T$ be the subgroup $\ZZ/4\ZZ \oplus (\ZZ/7\ZZ)^2$ of $A_T$. From \cite[Proposition 1.5.1]{Nikulin_1980}, we see that the primitive embedding $T \hookrightarrow \Lambda_0$ with orthogonal complement $S$ is determined by an isomorphism $\gamma\colon H_T \overset{\sim}{\to} H_S$ with $q_S \circ\gamma = -q_T$ (where $q_S$ and $q_T$ are their corresponding discriminant-quadratic forms). Also note that the projection $\Lambda_0^*/(S\oplus T) \to T^*/T=  A_T$ induces an embedding $A_{\Lambda_0} \to A_T$ to the copy of $\ZZ/3\ZZ$. 

    Now suppose $f \in \rO^+(T)$ satisfies that $\overline{f}|_{\ZZ/3\ZZ}$ is trivial. Note that from \cite[\S 4]{hohn2016290} we have $\rO(S) \to A_S = H_S$ being surjective, thus we can choose some $g \in \rO(S)$ such that $\overline{g} = \gamma \circ\overline{f} \circ \gamma^{-1}$. Therefore, also from \cite[Corollary 1.5.2]{Nikulin_1980}, we can extend $f$ to some $\widetilde{f} \in \rO^+(\Lambda_0)$ such that $\widetilde{f}|_T = f, \widetilde{f}|_S = g$. Note that $\widetilde{f} \in \widehat{\Gamma}$ since $\overline{f}|_{\ZZ/3\ZZ}$ is trivial. Meanwhile, $\widetilde{f}L_2(7)\widetilde{f}^{-1} = L_2(7)$ is easy to check, therefore, $f \in \Gamma$. 


    Conversely, any $f \in \Gamma$ is the image of some element in $\widehat{\Gamma}$, then $f|_{\ZZ/3\ZZ}$ is trivial. The proposition follows. 
\end{proof}


For each element $f \in \rO^+(T)$, if $\overline{f}|_{\ZZ/3\ZZ}$ is not trivial, then it sends $1$ to $-1$ in $\ZZ/3\ZZ$, thus $-f$ acts trivially on $\ZZ/3\ZZ$. Meanwhile, it is obvious that $-\Id \notin \Gamma$, therefore we have the following
\begin{prop}
    As a group, $\rO^+(T)$ is generated by $\Gamma$ and $-\Id$. And $\Gamma$ is an index $2$ subgroup of $\rO^+(T)$. 
\end{prop}


Let $\rO(1,2)$ be the orthogonal group of $T \otimes \mathbb{R}$, and identify $\rO^+(T) < \rO(1,2)$. Multiplying those elements in $\Gamma$ with determinant $-1$ by $-\Id$, we obtain an isomorphism from $\Gamma$ to $\Gamma^\prime = \rO^+(T) \cap \SO(1,2)$. The quotients of $\mathbb{D}_T$ by $\Gamma$ or $\Gamma^\prime$ are obviously the same, therefore we are reduced to considering $\Gamma^\prime = \rO^+(T) \cap \SO(1,2)$. 

\subsection{Tube Domain Model for the $L_2(7)$-family}
\label{tubedomainL27}
Let $e_1,e_2,e_3 \in T$ be the integral basis for which the Gram matrix is \eqref{equation: gram matrix of T}. Then $(e_1)^2=-2,(e_2)^2=10,(e_1,e_2)=1,(e_3)^2=-28$. Let $f,e,g \in T\otimes\mathbb{R}$ be an $\RR$-basis such that if we denote
\[
B = \begin{pmatrix}
    -\frac{\sqrt{21}}{42}-\frac{1}{2} & 0 & -\frac{\sqrt{21}}{42}+\frac{1}{2} \\
    -\frac{\sqrt{21}}{21} & 0 & -\frac{\sqrt{21}}{21} \\
    0 & \frac{\sqrt{14}}{14} & 0
\end{pmatrix},
\]
we have $\begin{pmatrix}
    f&e&g
\end{pmatrix} = \begin{pmatrix}
    e_1&e_2&e_3
\end{pmatrix}B.$ 

Note that
\[
B^TTB = \begin{pmatrix}
    0&0&1\\
    0&-2&0\\
    1&0&0
\end{pmatrix}
\]

Therefore, $f,g$ are isotropic and $(f,g) = 1, (e)^2=-2, (f,e)=0, (g,e) = 0$. 

With this basis, we can identify $T \otimes \RR$ with the quadratic space of binary forms over $\RR$, sending $\alpha f + \beta e + \gamma g$ to $\alpha x^2 + 2\beta xy + \gamma y^2$, where the quadratic form on this space is $Q(\alpha,\beta,\gamma) = -2\beta^2+2\alpha \gamma$. Note that $\beta^2-\alpha \gamma$ is the discriminant of the binary form $\alpha x^2 + 2\beta xy + \gamma y^2$. Each $h = \begin{pmatrix}
    a & b \\ c & d
\end{pmatrix} \in \SL(2, \RR)$ can be seen as an isometry on this space via the action
\[
h \cdot [\begin{pmatrix}
    x & y
\end{pmatrix} 
\begin{pmatrix}
    \alpha & \beta \\
    \beta & \gamma
\end{pmatrix}  
\begin{pmatrix}
    x \\ y
\end{pmatrix}]
 = 
\begin{pmatrix}
    x & y
\end{pmatrix} 
\begin{pmatrix}
    a & b \\ 
    c & d
\end{pmatrix}
\begin{pmatrix}
    \alpha & \beta \\
    \beta & \gamma
\end{pmatrix}  
\begin{pmatrix}
    a & b \\ 
    c & d
\end{pmatrix}^T
\begin{pmatrix}
    x \\ y
\end{pmatrix}
\]

With respect to the basis $f,e,g$, the action of $h$ corresponds to a matrix $A(h)\in \SO^+(1,2) = \SO^+(1,2;\RR)$. Straightforward calculation shows that 
\[A(h) = \begin{pmatrix}
    a^2 & 2ab & b^2 \\ ac & ad+bc & bd \\ c^2 & 2cd & d^2
\end{pmatrix}.\]
Let us denote $\Phi\colon \SL(2,\RR) \to \SO^+(1,2)$ be the morphism given by sending $h$ to $BA(h)B^{-1}$ (i.e. considering the basis $e_1,e_2,e_3$). This gives a surjective morphism $\SL(2,\RR) \to \SO^+(1,2)$ of degree two, which induces a group isomorphism $\PSL(2, \RR) \overset{\sim }{\to} \SO^+(1,2)$. 

Let $\mathbb{H} = \{z \in \CC|\Im(z)>0\}$ be the complex upper plane, with $\SL(2, \RR)$ acting on it by $h\cdot \frac{\omega_1}{\omega_2} = \frac{a\omega_1+b\omega_2}{c\omega_1+d\omega_2}$. it is easy to check that there is a biholomorphic morphism $\mathbb{H} \to \mathbb{D}_T$ sending $z$ to $z^2f + ze + g$, or equivalently sending $\frac{\omega_1}{\omega_2}$ to $\omega_1^2f + \omega_1\omega_2e+\omega_2^2g$, which is the classic tube domain model. As binary forms, we can write $\omega_1^2f + \omega_1\omega_2e+\omega_2^2g$ as $\begin{pmatrix}
    x & y
\end{pmatrix} 
\begin{pmatrix}
    \omega_1 \\ \omega_2
\end{pmatrix} 
\begin{pmatrix}
    \omega_1 & \omega_2
\end{pmatrix}
\begin{pmatrix}
    x \\ y
\end{pmatrix}.$ 
Therefore, we have the following equivariant diagram
\[ \begin{tikzcd}
\SL(2, \RR) \arrow{r}{\Phi} \arrow[symbol=\circlearrowright]{d} & \SO^+(1,2) \arrow[symbol=\circlearrowright]{d} \arrow[hook]{r} & \mathrm{O}(1,2) \arrow[symbol=\circlearrowright]{d} \\
\mathbb{H} \arrow{r}{\cong} & \mathbb{D}_T \arrow[hook]{r} & \mathbb{P}(T \otimes \CC)
\end{tikzcd}
\]

Next we characterize the curve $\mathbb{D}_T/\Gamma$ as an arithmetic quotient of $\mathbb{H}$. For this, we compute the inverse image $\Phi^{-1}(\Gamma^{\prime}) = \Phi^{-1}(\rO^+(T)\cap \SO^+(1,2))$. By definition, they are those $h \in \SL(2, \RR)$ such that $\Phi(h)$ has integer coefficients. 

\begin{prop}
\label{proposition:arithgroupofL27}
    Denote $\Gamma^{\prime \prime} = \Phi^{-1}(\rO^+(T)\cap \SO^+(1,2))$. We have 
\begin{align*}
    \Gamma^{\prime \prime} = &\{
    \begin{pmatrix}
        \frac{u\sqrt{u^\prime}+v\sqrt{v^\prime}}{2} & \frac{w\sqrt{w^\prime}+x\sqrt{x^\prime}}{2} \\
        \frac{w\sqrt{w^\prime}-x\sqrt{x^\prime}}{2} &
        \frac{u\sqrt{u^\prime}-v\sqrt{v^\prime}}{2}
    \end{pmatrix}|u,v,w,x \in \ZZ, (u^\prime, v^\prime, w^\prime, x^\prime) = (1,21,6,14)\  \text{or} \ (2,42,3,7)\\ &\text{up to permutation by }\mathrm{V} < \mathrm{S}_4, \text{and }u^2u^\prime - v^2v^\prime - w^2w^\prime + x^2x^\prime = 4\}
\end{align*}
(Here we use $\mathrm{V}=\{1, (12)(34), (13)(24),(14)(23)\}$ to denote the Klein $4$-group).
\end{prop}
\begin{proof}
    For any $h=\begin{pmatrix}
        a & b\\ c&d
    \end{pmatrix} \in \SL(2, \RR)$ such that $\Phi(h)$ has integer coefficients. Set $\Phi(h) = N = \begin{pmatrix}
        n_1 & n_2 & n_3 \\ n_4 & n_5 & n_6\\ n_7 & n_8 & n_9
    \end{pmatrix}$ with $n_i \in \ZZ$. Writing out $A(h) = B^{-1}NB$, we obtain this matrix
