\subsection{Commensurability Class of $\Gamma$}
\label{subsection: type of H as arith}
Recall that arithmetic subgroups of $\SL(2,\RR)$ up to commensurability and conjugacy have been completely classified, see for example \cite[Chapter 6]{morris2015introduction}. For reader's convenience, we gather these facts as below

\begin{defn}
    A closed subgroup $\Delta < \SL(2,\RR)$ is cocompact if $\SL(2,\RR)/\Delta$ is compact.  
\end{defn}

We borrow the following proposition \cite[Chapter 6, Proposition 6.1.5]{morris2015introduction}
\begin{prop}
\label{propositon:only noncocompact}
    $\SL(2,\ZZ)$ is the only noncocompact, arithmetic subgroup of $\SL(2,\RR)$ up to commensurability and conjugacy. 
\end{prop}

What is left is those cocompact arithmetic subgroups. We first recall what cocompact arithmetic subgroups can appear according to \cite[Proposition 6.2.4, Propsition 6.2.5 and Proposition 6.2.6]{morris2015introduction}.
\begin{defn}
\begin{enumerate}
    \item For any field $F$, and any nonzero $a,b \in F$, the corresponding quaternion algebra over $F$ is the ring
    \[
    \HH_F^{a,b} = \{p+qi+rj+sk|p,q,r,s\in F\},
    \]
    where
    \begin{itemize}
        \item addition is defined in the obvious way, and
        \item multiplication is determined by the relations
        \[
        i^2 = a, j^2 = b, ij=k=-ji
        \]
        together with the requirement that every element of $F$ is in the center of $\HH_F^{a,b}$. 
    \end{itemize}
    \item The reduced norm of $x = p+qi+rj+sk \in \HH_F^{a,b}$ is
    \[
    \mathrm{N}_{red}(x) = x\overline{x} = p^2-aq^2-br^2+abs^2 \in F
    \]
    where $\overline{x} = p-qj-rj-sk$ is the conjugate of $x$. 
\end{enumerate}
\end{defn}

For $a,b \in \RR^+$, there is an isomorphism of rings $\psi\colon \HH^{a,b}_\RR \xrightarrow{\sim} \mathrm{M}_{2\times2}(\RR)$ sending $i$ to $\begin{pmatrix}
    \sqrt{a}&0\\0&-\sqrt{a}
\end{pmatrix}$, $j$ to $\begin{pmatrix}
    0&1\\b&0
\end{pmatrix}$ and $k$ to $\begin{pmatrix}
    0&\sqrt{a}\\-b\sqrt{a} & 0
\end{pmatrix}$ such that $\mathrm{N}_{red}(x) = \det(\psi(x))$. Let $\SL(1, \HH^{a,b}_F)\coloneqq \{g\in \HH_F^{a,b}|\mathrm{N}_{red}(x) = 1\}$, then under the identification above, we have $\SL(2,\RR) = \SL(1, \HH^{a,b}_\RR)$. We recall the following fact according to \cite[Proposition 6.2.4, Proposition 6.2.5 and Proposition 6.2.6]{morris2015introduction}
\begin{prop}
\label{proposition:arithsubgrp}
    Every cocompact and arithmetic subgroup of $\SL(2,\RR)$ up to commensurability and conjugacy is of the following form
    \begin{itemize}
        \item $\SL(1, \HH_\ZZ^{a,b})< \SL(1, \HH_\RR^{a,b})\cong\SL(2,\RR)$, where $a,b \in \ZZ^+$ and $(0,0,0,0)$ is the only integer solution $(p,q,r,s)$ of the Diophantine equation\[
        w^2-ax^2-by^2+abz^2 = 0
        \]
        \item $\SL(1, \HH_\mathcal{O}^{a,b})<\SL(1,\HH_\RR^{a,b}) \cong \SL(2,\RR)$, where $\mathcal{O}$ is the ring of integers of a totally real algebraic number field $F \ne \QQ$ and $a,b\in \mathcal{O}$ are positive such that $\sigma(a)$ and $\sigma(b)$ are negative for every place $\sigma \ne \Id$. 
    \end{itemize}
\end{prop}

Next we show $\Gamma$ is a cocompact arithmetic subgroup of $\SL(2,\RR)$.

\begin{prop}
\label{proposition:cocompactness}
    The curve $\mathbb{D}_T/\Gamma$ is compact, and therefore not isogenous to $\PSL(2,\ZZ)\bs\HH$. 
\end{prop}
\begin{proof}
    By Proposition \ref{propositon:only noncocompact}, we only need to show that $\DD_T/\Gamma$ is compact. This can be shown by considering the Baily-Borel compactification. In fact, the boundaries of Baily-Borel compactification are the isotropic subspaces of $T\otimes \QQ$ \cite{baily1966compactification}. However, there is no isotropic vector. The claim is equivalent to that the equation $-x^{2}+xy+5y^{2}=14z^{2}$ has no coprime integer solution.

    If there is an integer solution $x,y,z$ with $\gcd(x,y,z)=1$, then  $x,y$ must be even integers. So $4$ divides $14z^{2}$ and thus $z$ is forced to be an even integer, a contradiction to the coprime assumption.
\end{proof}

\begin{rmk}
\label{rmk:compactnessfromGIT}
    The compactness of $\Gamma\backslash\mathbb{D}_{T}$ can also be deduced from the GIT analysis in Proposition \ref{singuL27}.

    More precisely, $\overline{\mathcal{F}}_{L_{2}(7)}\cong \mathbb{P}^{1}$ can be obtained from $\mathcal{F}_{L_{2}(7)}^{\mathrm{ADE}}$ by adding one point that corresponds to the determinantal cubic fourfold. And note that the point of determinantal cubic fourfold is of codimension 1. By Theorem \ref{thm:Yu--Zhengperiodmapsymmcubic4fold}, the period map:
    \begin{align*}
        \mathcal{F}_{L_{2}(7)}^{\mathrm{ADE}}\rightarrow \Gamma_{T}\bs(\mathbb{D}- \calH_{*})
    \end{align*}
extends to 
    \begin{align}
    \label{equation:periodmapL27}
\overline{\mathcal{F}}_{L_{2}(7)}\cong \overline{\Gamma_{T}\bs\mathbb{D}}^{\mathcal{H}_*}=\overline{\Gamma_{T}\bs\mathbb{D}}^{BB}.
    \end{align}
From analysis of singular cubic fourfolds in $\overline{\mathcal{F}}_{L_{2}(7)}$, the image of map \ref{equation:periodmapL27} should be $\Gamma_{T}\bs\mathbb{D}$. Therefore, $\Gamma_{T}\bs\mathbb{D}$ is itself compact.
\end{rmk}

In fact, we can further determine the type of $\HH$ as an arithmetic subgroup of $\SL(2, \RR)$

\begin{thm}
\label{theorem:typeofdomainL27}
   The curve $\DD_{T}/\Gamma$ is isogenous to $\HH/\SL(1, \HH_\ZZ^{21,6})$. 
\end{thm}

\begin{proof}
    We show $\SL(1, \HH_\ZZ^{21,6})<H$ up to a conjugation.

    Consider $A=\begin{pmatrix}
        0 & 6^{-\frac{1}{4}}\\
        -6^{\frac{1}{4}} & 0
    \end{pmatrix}$, 
     then 
     \[
     AHA^{-1}=\{
    \begin{pmatrix}
        \frac{u+v\sqrt{21}}{2} & \frac{3w-x\sqrt{21}}{6} \\
        3w+x\sqrt{21} &
        \frac{u-v\sqrt{21}}{2}
    \end{pmatrix}|u,v,w,x \in \ZZ, u^{2}-21v^{2}-6w^{2}+14x^{2}=4\}.
    \]

    For equation $u^{2}-21v^{2}-6w^{2}+14x^{2}=4$, we analyze modulo $3$ and obtain $u^{2}+2x^{2}\equiv 1  \, (\mathrm{mod}\,3)$. We must have $3| x$, otherwise $u^{2}\equiv -1 \, (\mathrm{mod}\,3)$, which is impossible. Replace $x$ by $3x$, and one obtains 
    \[
    AHA^{-1}=\{
    \begin{pmatrix}
        \frac{u+v\sqrt{21}}{2} & \frac{w-x\sqrt{21}}{2} \\
        6(\frac{w+x\sqrt{21}}{2}) &
        \frac{u-v\sqrt{21}}{2}
    \end{pmatrix}|u,v,w,x \in \ZZ, u^{2}-21v^{2}-6w^{2}+126x^{2}=4\}.
    \]

    And $\SL(1, \HH_\ZZ^{21,6})$ is a subgroup of $AHA^{-1}$ consisting of matrices where $u,v,w,x$ are even integers.

    Therefore, $\SL(1, \HH_\ZZ^{21,6})<\Gamma^{\prime \prime}$ and thus they are commensurable with each other, since both are arithmetic subgroups of $\SL(2,\RR)$. 

    Modulo 7 and using infinite descent, one can show that equation $u^{2}-21v^{2}-6w^{2}+126x^{2}=0$ does not have non-trivial integer solution. Therefore, $\SL(1, \HH_\ZZ^{21,6})$ satisfies the conditions in Proposition \ref{proposition:arithsubgrp}. 
\end{proof}


