\medmuskip = 1mu % default: 4mu plus 2mu minus 4mu
\begin{align*}
\left( \begin{array}{llllll} 
\frac{21(n_1+n_6)+(n_1+n_2+5n_5-n_6)\sqrt{21}}{42} & \frac{n_7-2n_3-n_7\sqrt{21}}{2} & \frac{2n_4-n_8+n_8\sqrt{21}}{14} & \frac{21(-n_1+n_5+n_6)+(n_1+2n_2-11n_5-n_6)\sqrt{21}}{42}  \\
\frac{-21n_9-(n_9+2n_{10})\sqrt{21}}{42} & n_{11} & -\frac{n_{12}}{7} & \frac{21n_9-(n_9+2n_{10})\sqrt{21}}{42} \\
\frac{21n_{13}+(n_{13}+2n_{14})\sqrt{21}}{6} & -7n_{15} & n_{16} & \frac{-21n_{13}+(n_{13}+2n_{14})\sqrt{21}}{6}  \\
