  \node at (2.5,0.5) {\small \textcolor{Blue}{$z_{53}$}}; 
  \node at (3.5,0.5) {\small \textcolor{Blue}{$z_{54}$}}; 
  \node at (2.5,3.5) {\small \textcolor{Blue}{$z_{23}$}};
