\subsection{Moving multipoints through tangencies.} We can move an intersection point through a tangency or a tangency nest, in several ways. Move (i) below is a basic version, moves (ii) and (iii) are its generalizations, and moves (iv) and (v) are variants. See Figure~\ref{fig:all-multipt-tang}.  These moves are more involved than the previous ones: they introduce additional braiding rather than simply switching the elements of the diagram.    Only moves (i) and (ii) will be used in Section~5, the rest are not needed until Section~7. 
For this type of move, one needs to be careful with various symmetric versions: because of the asymmetry in our chosen tangency model, the braiding is somewhat asymmetric.% We state two versions for some of the moves to avoid confusion about this asymmetry; the illustrations and the proofs are only given for one version. 



\noindent {\bf(i)} Moving a double point up or down through a tangency: 
\begin{equation}\label{eq:move-doublept-tang}
 \T_i \I_{i+1} =_\d \sigma_{i+1} \sigma_i^{-1} \T_{i+1} \I_i
  \end{equation}

\noindent {\bf (ii)} Moving a multipoint up or down through a tangency nest on the same strands:
\begin{equation}\label{eq:move-multipt-tang}
 \TN_{1, 2n} \I^1_{n} =_\d \Delta_{1,n} \Delta_{n+1, 2n}^{-1} \TN_{1, 2n} \I^{n+1}_{2n}
\end{equation}
where $\Delta_{j, k}$  stands for a positive half-twist on the collection of strands $j, \dots, k$. We stated the move for the tangency nest on strands $1, \dots, 2n$. 

 \noindent {\bf (iii)} Moving a strand through a tangency nest, with double point intersections: 
\begin{equation}\label{eq:move-strand-tang}
\TN_{1,2n}\I_{2n}\I_{2n-1}\dots\I_{n+1}=_\d \sigma_{2n}\sigma_{2n-1}\dots\sigma_{n+1}\sigma_n^{-1}\sigma_{n-1}^{-1}\dots\sigma_1^{-1}\TN_{1,2n}\I_1\I_2\dots\I_{n}.
\end{equation}

\noindent {\bf (iv)} Switching the order of a double point and a tangency:

\begin{equation}\label{eq:move-doublept-tang2}
\T_i\I_{i+1}=_\d \I_{i+1}\sigma_{i+1}\T_i\sigma_{i+1}^{-1}
\end{equation}




\noindent {\bf (v)}  Moving a multipoint to the other side of a tangency nest on the same strands:

\begin{equation}\label{eq:TNIswap2}
\TN_{1,2n}\I^1_n=_\d \I_{1,n}\Delta_{1,n}\TN_{1,2n}\Delta_{1,n}^{-1}
\end{equation}




