\X^{m-1, m}_{m+1, 2m} \I^{m-2}_{ 2m-2},
$$
producing the diagram 
$$
\Delta_{1,m} \Delta_{m+1, 2m}^{-1} \TN \I^{m+2}_{ 2m} \X^{m-1, m}_{m+1, 2m} \I^{m-2}_{ 2m-2}  \I^{m-3}_{ 2m-3} \dots \I^2_{ m+2} \I^1_{ m+1}
$$
in Figure~\ref{fig:ProofMoves}(e). Then similarly move up $\I^{m+2}_{ 2m}$ and combine with double points to get the diagram  
\begin{equation*}
 \begin{split}
&\Delta_{1,m} \Delta_{m+1, 2m}^{-1} \TN   \X^{m}_{m+1, 2m} \I^{m-1}_{m}  \I^m_{2m-2}   \I^{m-2}_{ 2m-2}  \I^{m-3}_{ 2m-3} \I^2_{ m+2} \I^1_{ m+1} =_\d  \\ 
