 & \Delta_{1,m} \Delta_{m+1, 2m}^{-1}   \TN_{2, 2m-1}
\sigma_{top}^{-1}  \sigma_{bot}^{-1}  \I^m_{m+1} \sigma_{m-1} \sigma_{m}^{-1} \T_{m-1} \X^{m}_{m+1, 2m} \I^m_{2m-1}  \I^{m-2}_{ 2m-2}  \I^{m-3}_{ 2m-3} \dots \I^2_{m+2} \I^1_{m+1}
